const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',wallet:'M3 6h16v15H3z M3 6l13-3v3 M15 11h6v5h-6z',send:'m5 19 14-14 M5 5h14v14',calendar:'M4 5h16v16H4z M8 3v4 M16 3v4 M4 10h16 M8 14h3 M8 17h6',route:'M5 5h12l-3-3 M17 5l-3 3 M19 19H7l3 3 M7 19l3-3 M5 5v8 M19 11v8',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6z m-4 9 3 3 5-6',history:'M3 11a9 9 0 1 1 2 7 M3 4v7h7 M12 7v6l4 2',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M9 3h6l1 4 4 1v8l-4 1-1 4H9l-1-4-4-1V8l4-1z',help:'M12 16h.01 M9 9a3 3 0 1 1 5 2l-2 1v1 M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',arrow:'M4 12h16m-5-5 5 5-5 5',down:'m5 9 7 7 7-7',plus:'M12 5v14 M5 12h14',bell:'M5 17h14l-2-4V9a5 5 0 0 0-10 0v4z M10 21h4',external:'M14 3h7v7 M21 3l-9 9 M10 5H4v15h15v-6',download:'M12 3v12m-5-5 5 5 5-5 M4 16v5h16v-5',check:'m5 12 4 4L19 6',close:'m6 6 12 12 M6 18 18 6',lock:'M6 10h12v11H6z M8 10V7a4 4 0 0 1 8 0v3',file:'M5 3h10l4 4v14H5z M9 11h6 M9 15h6',arrowDown:'m5 5 14 14 M5 19h14V5',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M12 9a3 3 0 1 0 0 6 3 3 0 0 0 0-6'};
const icon=(n,size=18)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:2}).format(n);
let saved;try{saved=JSON.parse(localStorage.getItem('vectra-demo')||'{}')}catch{saved={}};
let state={page:'Overview',connected:false,filter:'All',range:'This month',proposals:saved.proposals||[],schedules:saved.schedules||[]};
const persist=()=>localStorage.setItem('vectra-demo',JSON.stringify({proposals:state.proposals,schedules:state.schedules}));
const navs=[['Overview','grid'],['Wallets & assets','wallet'],['Distributions','calendar'],['Cross-chain routing','route'],['Approvals','shield'],['Activity log','history']];
const initialTx=[{name:'Monthly contributor payout',sub:'Distribution · 12 recipients',amount:'− $18,000.00',status:'Completed',date:'Oct 21, 2026',icon:'send'},{name:'Treasury funding',sub:'Deposit · USDC',amount:'+ $50,000.00',status:'Completed',date:'Oct 20, 2026',icon:'arrowDown'},{name:'Solana → Ethereum',sub:'Routing · MultiHopper simulation',amount:'− $25,000.00',status:'Draft',date:'Oct 19, 2026',icon:'route'},{name:'Operations wallet top-up',sub:'Transfer · USDC',amount:'− $2,500.00',status:'Completed',date:'Oct 18, 2026',icon:'send'}];
const initialSchedules=[{name:'Contributor payroll',recipients:12,amount:18000,date:'Oct 28, 2026',frequency:'Monthly'},{name:'Operations top-up',recipients:3,amount:9000,date:'Nov 01, 2026',frequency:'Weekly'},{name:'Ecosystem grants',recipients:5,amount:15000,date:'Nov 05, 2026',frequency:'One-time'}];
function notify(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),3800)}
function navigate(page){state.page=page;state.filter='All';render();window.scrollTo(0,0)}
function shell(){return `<aside><div class="brand"><svg class="logo vectra-mark" width="31" height="31" viewBox="0 0 36 36" fill="none" aria-hidden="true"><path d="M3 7 17.5 31 32 7H25L17.5 20 10 7Z" fill="currentColor"/><path d="m16 7 4 7 4-7" stroke="currentColor" stroke-width="2.5"/><circle cx="31" cy="29" r="2" fill="currentColor"/></svg><span class="word">VECTRA<small>TREASURY OPERATIONS</small></span></div><div class="workspace"><span class="avatar workspace-monogram">V/</span><div>Demo treasury<small>Solana workspace</small></div>${icon('down',12)}</div><div class="nav-label">WORKSPACE</div><nav class="nav">${navs.map(([n,i])=>`<button data-page="${n}" class="${state.page===n?'active':''}">${icon(i)}<span>${n}</span>${n==='Approvals'?`<b class="badge">${state.proposals.filter(p=>p.status==='Pending approval').length+2}</b>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><nav class="nav"><button data-page="Settings">${icon('settings')}<span>Settings</span></button><button data-page="Help & roadmap">${icon('help')}<span>Help & roadmap</span></button></nav><div class="safe">${icon('shield',16)} &nbsp; Capital in motion.<br>Control by design.<p>Plan. Approve. Move.<br>Every step, accountable.</p></div><div class="profile"><span class="avatar">VT</span><div style="font-size:11px;color:#dce9de">Treasury team<br><small>Workspace admin</small></div><span style="margin-left:auto">${icon('down',12)}</span></div></div></aside><main><header><div class="crumb">Workspace <span>/</span> <strong>${state.page}</strong></div><div class="mobile-brand">VECTRA<span>/</span></div><div class="header-actions"><span class="network"><i class="dot"></i> Solana Devnet ${icon('down',11)}</span><button class="icon-btn" data-action="notifications" aria-label="Notifications">${icon('bell',18)}</button><button class="btn" data-action="connect">${icon('wallet')} ${state.connected?'Demo wallet · 7xKp…8nQ4':'Connect wallet'}</button></div></header><div class="content" id="content"></div></main><nav class="mobile-nav">${navs.slice(0,5).map(([n,i])=>`<button data-page="${n}" class="${state.page===n?'active':''}">${icon(i)}${n==='Wallets & assets'?'Assets':n==='Cross-chain routing'?'Routing':n}</button>`).join('')}</nav>`}
function pageHeading(title,subtitle,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`}
function statusClass(s){return s==='Completed'?'':s==='Pending approval'?'pending':'draft'}
function txTable(all=false){let rows=[...state.proposals.map(p=>({name:p.name,sub:p.type+' · Demo proposal',amount:'− '+money(p.amount),status:p.status,date:'Just now',icon:p.type==='Routing'?'route':'send'})),...initialTx];if(state.filter!=='All')rows=rows.filter(r=>r.status===state.filter);if(!all)rows=rows.slice(0,4);return `<div class="table-wrap"><table><thead><tr><th>Transaction</th><th>Amount</th><th>Status</th><th>Date</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><div class="tx-name"><span class="tx-icon">${icon(r.icon,14)}</span><div>${esc(r.name)}<small>${esc(r.sub)}</small></div></div></td><td class="amount">${r.amount}</td><td><span class="status ${statusClass(r.status)}">${r.status}</span></td><td style="color:#8c9886">${r.date}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No transactions match this filter.</td></tr>'}</tbody></table></div>`}
function scheduleItems(full=false){return [...state.schedules,...initialSchedules].slice(0,full?99:3).map(s=>`<div class="schedule-item"><div class="schedule-line"><div class="schedule-title">${esc(s.name)}<small>${s.recipients} recipients · USDC</small></div><div class="schedule-amount">${money(s.amount).replace('.00','')}</div></div><div class="schedule-date"><span>${icon('calendar',11)} ${esc(s.date)}</span><span class="status ${s.local?'pending':''}">${s.local?'Needs approval':s.frequency}</span></div></div>`).join('')}
function overview(){return pageHeading('Treasury overview','The operational view of your capital.',`<button class="btn" data-action="export">${icon('download')} Export report</button><button class="btn" data-action="range">${icon('calendar')} ${state.range} ${icon('down',11)}</button>`)+`<section class="brand-banner"><div class="brand-banner-copy"><div class="brand-kicker"><span class="brand-live"></span> VECTRA / SOLANA TREASURY OPERATIONS</div><h2>Treasury, in motion.</h2><p>Treasury operations at the speed of Solana.</p><div class="brand-principles"><span>01 <b>Plan.</b></span><span>02 <b>Approve.</b></span><span>03 <b>Move.</b></span></div></div><div class="brand-orbit" aria-hidden="true"><svg viewBox="0 0 380 180"><defs><linearGradient id="routeGlow"><stop stop-color="#174f3e"/><stop offset="1" stop-color="#b7f59a"/></linearGradient></defs><path d="M-10 145H95L164 36h90l65 108h75 M-10 165H106L175 56h68l65 108h86 M-10 125H84L153 16h112l65 108h64" stroke="url(#routeGlow)" stroke-width="1.2" fill="none"/><circle cx="254" cy="36" r="5" fill="#b7f59a"/><circle cx="95" cy="145" r="4" fill="#a4d6af"/><path d="m225 23 18 31 18-31h-8l-10 17-10-17z" fill="#c9f5d8"/></svg><span>CAPITAL → COORDINATED</span></div></section><div class="summary"><section class="balance-card"><div><div class="balance-label">Total treasury balance <span class="demo-tag">DEMO DATA</span></div><div class="balance">$248,500<span class="cents">.00</span></div><div class="gain"><strong>↗ 12.8%</strong> vs. previous ${state.range==='This month'?'month':'period'} · illustrative</div><div class="balance-foot"><div>Available to spend<strong>$206,500.00</strong></div><div>Reserved for payouts<strong>$42,000.00</strong></div></div></div><div class="chart"><div class="chart-label"><span>TREASURY VALUE</span><span>USDC</span></div><svg viewBox="0 0 310 125" preserveAspectRatio="none"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#82ab65" stop-opacity=".27"/><stop offset="1" stop-color="#82ab65" stop-opacity="0"/></linearGradient></defs><path d="M0 95 14 91 25 96 40 78 53 82 66 66 80 74 93 54 106 60 118 48 132 54 146 35 159 44 174 25 187 34 198 29 211 40 223 22 236 30 248 13 261 19 274 7 290 10 309 3V125H0Z" fill="url(#area)"/><path d="M0 95 14 91 25 96 40 78 53 82 66 66 80 74 93 54 106 60 118 48 132 54 146 35 159 44 174 25 187 34 198 29 211 40 223 22 236 30 248 13 261 19 274 7 290 10 309 3" fill="none" stroke="#70914e" stroke-width="2"/><circle cx="309" cy="3" r="4" fill="#638549" stroke="#ddefd9" stroke-width="3"/></svg><div class="chart-bottom"><span>OCT 01</span><span>OCT 07</span><span>OCT 14</span><span>OCT 22</span></div></div></section><section class="quick"><div class="card-heading"><h2>Treasury actions</h2><span class="subtle">PROTOTYPE</span></div><div class="quick-grid">${[['Send USDC','send','send'],['Schedule','calendar','schedule'],['Route funds','route','route'],['Approvals','shield','approvals']].map(([n,i,a])=>`<button data-action="${a}"><span class="action-icon">${icon(i,17)}</span>${n}</button>`).join('')}</div><div class="quick-note">${icon('lock',11)} Wallet-controlled. Always.</div></section></div><div class="metrics"><div class="metric"><div class="metric-top">Scheduled payouts ${icon('calendar')}</div><div class="metric-value">$42,000 <span>3 schedules</span></div><p>Upcoming in the next 30 days</p></div><div class="metric"><div class="metric-top">Routed volume ${icon('route')}</div><div class="metric-value">$1.2M <span>↗ 18.4%</span></div><p>Illustrative all-time volume</p></div><div class="metric"><div class="metric-top">Pending approvals ${icon('shield')}</div><div class="metric-value">${state.proposals.filter(p=>p.status==='Pending approval').length+2} <span style="color:#a08745;background:#faf5e8">Action required</span></div><p>Awaiting authorized signatures</p></div></div><div class="lower"><section class="panel"><div class="panel-head"><h2>Recent activity</h2><button class="text-btn" data-page="Activity log">View all activity ${icon('arrow',13)}</button></div>${txTable()}<div class="table-bottom"><span>Illustrative transactions · no funds moved</span><span>All assets in USD</span></div></section><section class="panel"><div class="panel-head"><h2>Upcoming distributions</h2>${icon('calendar',16)}</div>${scheduleItems()}<button class="btn new-schedule" data-action="schedule">${icon('plus',13)} Create a schedule</button></section></div><div class="bottom-strip"><span>${icon('shield',15)} <strong>Control at every step.</strong> Plan distributions. Review proposals. Authorize movement.</span><span><i class="dot"></i> Solana Devnet</span></div>`}
function routing(){return pageHeading('Cross-chain routing','One treasury. More possibilities.',`<span class="pill">MultiHopper integration preview</span>`)+`<div class="lower"><section class="panel form-panel"><h2>Move USDC across chains</h2><p style="margin-top:8px">Build and review a cross-chain treasury proposal.</p><form id="route-form"><div class="route-visual"><div class="chain"><span class="chain-logo">≋</span>Solana</div>${icon('arrow')}<div class="chain"><span class="chain-logo" style="background:#eeeff6;color:#7a83aa">◆</span><select id="destination" aria-label="Destination chain" style="border:0;background:none"><option>Ethereum</option><option>Base</option><option>Arbitrum</option></select></div></div><div class="field"><label for="route-amount">Amount · USDC</label><input id="route-amount" type="number" min="1" max="206500" step="0.01" placeholder="10,000.00" value="10000" required><small>Demo available balance: 206,500.00 USDC</small></div><div class="field"><label for="route-address">Destination wallet</label><input id="route-address" placeholder="0x…" pattern="0x[a-fA-F0-9]{40}" required><small>Enter a valid EVM address on the selected destination chain.</small></div><div class="notice">Simulation only. MultiHopper API access, supported routes, fees and settlement must be verified before live execution. This demo does not request a live quote or send funds.</div><button class="btn primary" type="submit" style="width:100%">Review simulated route ${icon('arrow')}</button></form></section><section class="panel" style="align-self:start;padding:23px"><h2>A clear path for every transfer</h2><div style="padding:23px 0;line-height:2.1;font-size:12px;color:#7c8b74">1. Get a supported, live quote<br>2. Review total costs and received USDC<br>3. Collect treasury approvals<br>4. Sign with an authorized wallet<br>5. Monitor through settlement</div><div class="notice">Live routing is not configured. No simulated transfer counts as qualifying volume.</div></section></div>`}
function assets(){return pageHeading('Wallets & assets','A clear view of your Solana treasury.',`<button class="btn primary" data-action="connect">${icon('wallet')} ${state.connected?'Manage demo wallet':'Connect wallet'}</button>`)+`<div class="section-intro"><h2>${state.connected?'Demo treasury connected':'Explore your demo treasury'}</h2><p style="margin-top:8px">Illustrative balances are displayed below. This prototype does not read live RPC balances or request transaction signatures.</p></div><section class="panel"><div class="panel-head"><h2>Treasury assets</h2><span class="pill">Solana Devnet · Demo data</span></div><div class="table-wrap"><table><thead><tr><th>Asset</th><th>Token standard</th><th>Balance</th><th>Value (USD)</th></tr></thead><tbody><tr><td><div class="tx-name"><span class="chain-logo" style="background:#edf4fa;color:#3874b3">$</span><div>USD Coin<small>USDC · Demo</small></div></div></td><td>SPL Token</td><td>245,000.00 USDC</td><td class="amount">$245,000.00</td></tr><tr><td><div class="tx-name"><span class="chain-logo">≋</span><div>Solana<small>SOL · Demo</small></div></div></td><td>Native</td><td>20.00 SOL</td><td class="amount">$3,500.00</td></tr></tbody></table></div></section><div class="notice">Token-2022 discovery and token-specific transfer restrictions are planned for the live integration.</div>`}
function distributions(){return pageHeading('Distributions','Keep your team funded. Keep control of every payment.',`<button class="btn primary" data-action="schedule">${icon('plus')} Create schedule</button>`)+`<div class="section-intro"><h2>Scheduled, never automatic spending.</h2><p style="margin-top:7px">Schedules generate proposals for authorized signers. Creating a schedule does not grant spending authority or move treasury funds. Demo schedules are stored in this browser.</p></div><section class="panel"><div class="panel-head"><h2>Payment schedules</h2><span class="pill">${state.schedules.length+3} schedules</span></div>${scheduleItems(true)}</section>`}
function approvals(){let items=[...state.proposals,{id:'seed-1',name:'October contributor payroll',amount:18000,status:'Pending approval',type:'Distribution',seed:true},{id:'seed-2',name:'Operations wallet funding',amount:2500,status:'Pending approval',type:'Transfer',seed:true}];return pageHeading('Approvals','Every payment deserves a clear trail.')+`<div class="section-intro"><h2>Wallet-controlled execution</h2><p style="margin-top:7px">Demo approvals model a 2-of-3 treasury policy. Squads is not connected. Approving here records a local review only; it never signs or executes an on-chain transaction.</p></div><section class="panel"><div class="panel-head"><h2>Transaction proposals</h2><span class="pill">Demo policy · 2 of 3 signers</span></div>${items.map(p=>`<div class="audit-row"><div><strong>${esc(p.name)}</strong><small>${esc(p.type)} · ${money(p.amount)} USDC · ${p.status==='Reviewed'?'1 local review · 0 on-chain signatures':'0 of 2 signatures'}</small></div><div style="display:flex;align-items:center;gap:12px"><span class="status ${statusClass(p.status)}">${p.status}</span><button class="btn" data-review="${p.id}">Review ${icon('arrow',13)}</button></div></div>`).join('')}</section>`}
function activity(){return pageHeading('Activity log','An accountable record of treasury operations.',`<button class="btn" data-action="export">${icon('download')} Export CSV</button>`)+`<div class="section-intro"><p>This is an illustrative activity log plus proposals created in this browser. No on-chain signatures exist for demo entries. Verifiable signatures and Solana Explorer links appear only after a real transaction is submitted.</p></div><section class="panel"><div class="panel-head"><h2>All activity</h2><div class="filters">${['All','Completed','Pending approval','Draft'].map(f=>`<button class="filter ${state.filter===f?'active':''}" data-filter="${f}">${f==='Pending approval'?'Pending':f}</button>`).join('')}</div></div>${txTable(true)}<div class="table-bottom"><span>Demo records · not a tamper-evident ledger</span><span>No funds moved</span></div></section>`}
function help(){return pageHeading('Build roadmap','A focused path from demo to production.')+`<div class="section-intro"><h2>Treasury operations at the speed of Solana.</h2><p style="margin-top:10px">The MVP prioritizes scheduled USDC distributions and one verified MultiHopper route. The backend prepares and monitors proposals; treasury keys remain with authorized wallets.</p></div><div class="roadmap">${[['01–05','Connect & discover','Next.js UI, Wallet Standard and reliable RPC.','Connect and view live balances.'],['06–10','Fund operations','USDC builder, recipient lists and schedules.','Sign and send Devnet payments.'],['11–15','Route treasury','Verified MultiHopper adapter, costs and status.','Demonstrate one supported route.'],['16–20','Approve & audit','Squads, retries, logs and security checks.','Approval through settlement.'],['21–25','Launch & monitor','Production infrastructure and onboarding.','Working public MVP.']].map(([day,title,copy,accept])=>`<div class="panel"><div class="eyebrow">Days ${day}</div><h3>${title}</h3><p>${copy}</p><p style="margin-top:15px;color:#527647">${accept}</p></div>`).join('')}</div><div class="notice">Routing availability, supported chains, route accounting and qualification rules are integration gates. The 25-day plan is a roadmap, not a claim that this prototype is production ready.</div><section class="panel" style="padding:24px;margin-top:22px"><h2>Illustrative $30M volume scenario</h2><div class="quote-row"><span>10 operators × $3M qualifying volume</span><strong>$30,000,000</strong></div><div class="quote-row"><span>Stated 0.25% partner share</span><strong>$75,000</strong></div><p style="margin-top:15px">Before exclusions, costs and negotiated adjustments. This is a scenario, not earned revenue or verified partnership terms.</p></section>`}
function settings(){return pageHeading('Workspace settings','A transparent view of this demo environment.')+`<section class="panel form-panel"><h2>Environment</h2>${[['Network','Solana Devnet · Prototype'],['Wallet signing','Not configured'],['MultiHopper','Simulation only'],['Squads multisig','Not configured'],['Schedule storage','This browser only'],['Execution policy','Proposals require authorized signatures']].map(([a,b])=>`<div class="quote-row"><span>${a}</span><strong>${b}</strong></div>`).join('')}<div class="notice">A live implementation requires verified provider credentials, durable storage, scheduled workers and on-chain signing flows.</div><button class="btn" data-action="reset">Reset local demo data</button></section>`}
function render(){document.getElementById('app').innerHTML=shell();let pages={'Overview':overview,'Wallets & assets':assets,'Distributions':distributions,'Cross-chain routing':routing,'Approvals':approvals,'Activity log':activity,'Settings':settings,'Help & roadmap':help};document.getElementById('content').innerHTML=(pages[state.page]||overview)()+`<footer class="footer"><span>VECTRA © 2026 &nbsp;·&nbsp; Interactive prototype · Illustrative data only.</span><a class="brand-guide-link" href="/brand.html">Brand & market strategy ${icon('external',11)}</a></footer>`;document.querySelector('#route-form')?.addEventListener('submit',routeReview)}
function modal(title,body){document.getElementById('modal-root').innerHTML=`<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="${title}"><div class="modal-header"><h2>${title}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">${icon('close')}</button></div>${body}</section></div>`;document.querySelector('.modal input, .modal button')?.focus()}
function close(){document.getElementById('modal-root').innerHTML=''}
function connect(){modal(state.connected?'Demo wallet connected':'Connect your treasury',`<p>Explore the treasury with an illustrative wallet. Live Wallet Standard connection and RPC balances are not configured in this prototype.</p><button class="wallet-option" data-action="demo-connect"><span class="avatar">V</span><div><strong>${state.connected?'Disconnect demo wallet':'Use demo wallet'}</strong><p>Solana Devnet · No signature required</p></div>${icon('arrow')}</button><div class="notice">Your private keys are never requested or stored. No real funds are accessible in demo mode.</div>`)}
function paymentForm(scheduled=false){modal(scheduled?'Create a distribution':'Send USDC',`<p>${scheduled?'Create a one-time or recurring proposal for your recipients.':'Prepare a payment proposal for treasury approval.'}</p><form id="payment-form"><div class="field"><label for="payment-name">${scheduled?'Schedule name':'Payment reference'}</label><input id="payment-name" maxlength="70" required placeholder="e.g. Contributor payroll"></div><div class="field"><label>Recipients & USDC amounts</label><div id="recipients">${recipientRow()}</div><button type="button" class="text-btn" data-action="add-recipient">${icon('plus',13)} Add recipient</button><small>Use a Solana base58 wallet address. Maximum 20 recipients.</small></div>${scheduled?`<div class="form-row"><div class="field"><label for="payment-date">First proposal date</label><input id="payment-date" type="date" min="2026-10-22" value="2026-10-28" required></div><div class="field"><label for="frequency">Frequency</label><select id="frequency"><option>One-time</option><option>Weekly</option><option>Monthly</option></select></div></div>`:''}<div class="notice">Demo only. This creates a local proposal. No USDC is sent, and no automatic spending permission is granted.</div><div class="error" id="form-error" role="alert"></div><button class="btn primary full" type="submit">${scheduled?'Create demo schedule':'Create payment proposal'} ${icon('arrow')}</button></form>`);document.getElementById('payment-form').addEventListener('submit',e=>submitPayment(e,scheduled))}
function recipientRow(){return `<div class="recipient"><input aria-label="Recipient wallet address" placeholder="Solana wallet address" pattern="[1-9A-HJ-NP-Za-km-z]{32,44}" required><input aria-label="Amount in USDC" placeholder="USDC" type="number" min="0.01" max="206500" step="0.01" required></div>`}
function submitPayment(e,scheduled){e.preventDefault();let rows=[...document.querySelectorAll('.recipient')],addresses=rows.map(r=>r.children[0].value),total=rows.reduce((n,r)=>n+Number(r.children[1].value),0);if(new Set(addresses).size!==addresses.length){document.getElementById('form-error').textContent='Each recipient address must be unique.';return}if(total>206500){document.getElementById('form-error').textContent='Total exceeds the illustrative available balance.';return}let name=document.getElementById('payment-name').value.trim();if(!name)return;let proposal={id:crypto.randomUUID(),name,amount:total,status:'Pending approval',type:scheduled?'Distribution':'Transfer',recipients:rows.length};state.proposals.unshift(proposal);if(scheduled){let date=document.getElementById('payment-date').value;state.schedules.unshift({name,amount:total,recipients:rows.length,date:new Date(date+'T12:00:00Z').toLocaleDateString('en-US',{month:'short',day:'2-digit',year:'numeric',timeZone:'UTC'}),frequency:document.getElementById('frequency').value,local:true})}persist();close();render();notify(scheduled?'Demo schedule created. Authorized signatures still required.':'Payment proposal created. No funds have moved.')}
function routeReview(e){e.preventDefault();let amount=Number(document.getElementById('route-amount').value),chain=document.getElementById('destination').value,address=document.getElementById('route-address').value;modal('Review simulated route',`<p>Solana → ${chain} · USDC</p><div class="quote-row"><span>Send amount</span><strong>${money(amount)} USDC</strong></div><div class="quote-row"><span>Route fees</span><strong>Not available</strong></div><div class="quote-row"><span>Destination received</span><strong>Requires live quote</strong></div><div class="quote-row"><span>Settlement time</span><strong>Not verified</strong></div><div class="field"><label>Destination wallet</label><small style="word-break:break-all">${esc(address)}</small></div><div class="notice">This is a route preview, not a MultiHopper quote. Supported chains and all costs remain unverified. No transfer will be executed.</div><button class="btn primary full" id="save-route">Save demo route proposal</button>`);document.getElementById('save-route').onclick=()=>{state.proposals.unshift({id:crypto.randomUUID(),name:'Solana → '+chain,amount,status:'Draft',type:'Routing'});persist();close();navigate('Approvals');notify('Route draft saved. Live quote required before approval.')}}
function review(id){let p=state.proposals.find(p=>p.id===id)||{name:id==='seed-1'?'October contributor payroll':'Operations wallet funding',amount:id==='seed-1'?18000:2500,seed:true,type:'Transfer'};modal('Review treasury proposal',`<p>${esc(p.name)}</p><div class="quote-row"><span>Amount</span><strong>${money(p.amount)} USDC</strong></div><div class="quote-row"><span>Approval policy</span><strong>2 of 3 signatures</strong></div><div class="quote-row"><span>On-chain signature</span><strong>Not submitted</strong></div><div class="notice">${p.type==='Routing'?'Live routing and costs must be verified first.':'A local review is not an on-chain signature. Squads integration and authorized wallet signatures are required to execute.'}</div><button class="btn primary full" id="local-review">${p.type==='Routing'?'Return to routing':'Record local review'}</button>`);document.getElementById('local-review').onclick=()=>{if(p.type==='Routing'){close();navigate('Cross-chain routing');return}if(!p.seed){p.status='Reviewed';persist()}close();render();notify(p.seed?'Illustrative proposal reviewed. No signature requested.':'Local review recorded. On-chain signatures still required.')}}
function exportReport(){let rows=[['Reference','Type','Amount USDC','Status','Environment'],...initialTx.map(t=>[t.name,t.sub,t.amount,t.status,'Fictional demo data']),...state.proposals.map(p=>[p.name,p.type,p.amount,p.status,'Local demo proposal'])];const safe=v=>{let s=String(v);if(/^[=+\-@\t\r]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};let blob=new Blob([rows.map(r=>r.map(safe).join(',')).join('\r\n')],{type:'text/csv'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='vectra-demo-treasury-report.csv';a.click();URL.revokeObjectURL(a.href);notify('Demo treasury report exported.')}
document.addEventListener('click',e=>{let page=e.target.closest('[data-page]');if(page){navigate(page.dataset.page);return}let filter=e.target.closest('[data-filter]');if(filter){state.filter=filter.dataset.filter;render();return}let rev=e.target.closest('[data-review]');if(rev){review(rev.dataset.review);return}let action=e.target.closest('[data-action]')?.dataset.action;switch(action){case'connect':connect();break;case'close':close();break;case'demo-connect':state.connected=!state.connected;close();render();notify(state.connected?'Demo wallet connected. Illustrative balances only.':'Demo wallet disconnected.');break;case'send':paymentForm();break;case'schedule':paymentForm(true);break;case'route':navigate('Cross-chain routing');break;case'approvals':navigate('Approvals');break;case'add-recipient':if(document.querySelectorAll('.recipient').length<20)document.getElementById('recipients').insertAdjacentHTML('beforeend',recipientRow());else notify('Maximum 20 recipients in this demo.');break;case'notifications':modal('Treasury notifications','<div class="notice">2 illustrative proposals await authorized signatures.</div><p>Demo mode is active. No real transfers or automatic payments have been initiated.</p><button class="btn full" data-action="approvals-close">View approvals</button>');break;case'approvals-close':close();navigate('Approvals');break;case'export':exportReport();break;case'range':state.range=state.range==='This month'?'Last 30 days':'This month';render();notify('Demo totals remain illustrative for both periods.');break;case'reset':modal('Reset demo data?','<p>Remove proposals and schedules created in this browser. Illustrative sample records will remain.</p><button class="btn primary full" data-action="confirm-reset">Reset local demo</button>');break;case'confirm-reset':state.proposals=[];state.schedules=[];persist();close();render();notify('Local demo data reset.');break;}if(e.target.classList.contains('overlay'))close()});
document.addEventListener('keydown',e=>{if(e.key==='Escape')close();if(e.key==='Tab'&&document.querySelector('.modal')){let elements=[...document.querySelectorAll('.modal button,.modal input,.modal select')];let first=elements[0],last=elements.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});render();
